CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(80) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS programs (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(12) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, active TINYINT NOT NULL DEFAULT 1, curriculum_note VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS academic_periods (id INT AUTO_INCREMENT PRIMARY KEY, academic_year VARCHAR(12) NOT NULL, semester VARCHAR(20) NOT NULL, UNIQUE KEY period_unique (academic_year,semester));
CREATE TABLE IF NOT EXISTS subjects (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, units INT NOT NULL DEFAULT 3, synthetic TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS curriculum_subjects (id INT AUTO_INCREMENT PRIMARY KEY, program_id INT NOT NULL, subject_id INT NOT NULL, year_level INT NOT NULL, semester VARCHAR(20) NOT NULL, UNIQUE KEY assignment_unique (program_id,subject_id,year_level,semester), FOREIGN KEY (program_id) REFERENCES programs(id), FOREIGN KEY (subject_id) REFERENCES subjects(id));
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, public_code VARCHAR(60) NOT NULL UNIQUE, program_id INT NOT NULL, synthetic TINYINT NOT NULL DEFAULT 1, FOREIGN KEY (program_id) REFERENCES programs(id));
CREATE TABLE IF NOT EXISTS enrollments (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, period_id INT NOT NULL, program_id INT NOT NULL, year_level INT NOT NULL, academic_record_id INT NOT NULL UNIQUE, UNIQUE KEY enrollment_unique (student_id,period_id), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (period_id) REFERENCES academic_periods(id), FOREIGN KEY (program_id) REFERENCES programs(id), FOREIGN KEY (academic_record_id) REFERENCES academic_records(id));
CREATE TABLE IF NOT EXISTS subject_grades (id INT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, curriculum_subject_id INT NOT NULL, grade DECIMAL(4,2) DEFAULT NULL, attendance_rate DECIMAL(5,2) NOT NULL, completed TINYINT NOT NULL DEFAULT 1, UNIQUE KEY grade_unique (enrollment_id,curriculum_subject_id), FOREIGN KEY (enrollment_id) REFERENCES enrollments(id), FOREIGN KEY (curriculum_subject_id) REFERENCES curriculum_subjects(id));
CREATE TABLE IF NOT EXISTS dataset_imports (id INT AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(180) NOT NULL, data_class VARCHAR(30) NOT NULL, row_count INT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
